async function api(path,method='GET',body,key){const n=epoch,who=ABCentral?.actor?.id;const result=await ABCentral.api(path,method,body,method==='GET'?undefined:(key||uid()),{timeoutMs:30000,control:false});if(n!==epoch||who!==ABCentral?.actor?.id)throw Error('staleSession');return result;}
const snapshot=d=>JSON.stringify({...d,duplicateReview:d.duplicateReview||''});
const coName=id=>{const co=cap?.companies.find(c=>c.id===id);return co?(getLocale()==='ar'?co.arabicName:co.englishName):t('شركة خارج نطاق العرض','Company outside display scope');};
